import axios from "axios";

const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736"; // 🔁 여기에 실제 API 키 입력
const BASE_URL = "https://api.themoviedb.org/3";
const IMAGE_BASE_URL = "https://image.tmdb.org/t/p/w500";

/**
 * TMDB에서 영화 포스터를 가져오는 함수
 * @param {string} title - 영화 제목
 * @param {string} year - 개봉 연도 (YYYY 형식)
 * @param {object} options - 추가 옵션 (감독명, 국가 등)
 * @returns {string|null} 포스터 URL 또는 null
 */
export const getPosterFromTMDB = async (title, year, options = {}) => {
  try {
    const response = await axios.get(`${BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: title,
        language: "ko-KR",
        primary_release_year: year,
        include_adult: false,
        // region: "KR", ← 한국 영화 한정 X
      },
    });

    const results = response.data.results;

    if (!results || results.length === 0) return null;

    // 🎯 필터링 로직
    const filtered = results.find((movie) => {
      const releaseYear = movie.release_date?.substring(0, 4);
      const matchYear = releaseYear === year;
      const matchDirector = options.directorName
        ? movie.overview?.includes(options.directorName)
        : true;
      const matchNation = options.nation
        ? !options.nation.includes("한국") // 한국 영화 우선 제외
        : true;

      return matchYear && matchDirector && matchNation;
    });

    const selected = filtered || results[0];

    if (selected.poster_path) {
      return `${IMAGE_BASE_URL}${selected.poster_path}`;
    } else if (selected.backdrop_path) {
      return `${IMAGE_BASE_URL}${selected.backdrop_path}`;
    } else {
      return null;
    }
  } catch (error) {
    console.error("TMDB 포스터 요청 오류:", error);
    return null;
  }
};
